"""key 归一化. 导出报表与索引都走这里."""
from __future__ import annotations

import unicodedata


def normalize_key(raw: str) -> str:
    """对外部 key 做 NFKC 归一, 去首尾空白, 转小写."""
    return unicodedata.normalize("NFKC", raw).strip().lower()

